#include <unordered_map>

#include <opencv2/core/persistence.hpp>

#include "rmvlpara/camera/hik_camera.h"

namespace rm::para
{


bool HikCameraParam::load(const std::string &path)
{
    cv::FileStorage fs(path, cv::FileStorage::READ);
    if (!fs.isOpened())
        return false;
    cv::FileNode node;

    node = fs["exposure"];
    node.isNone() ? void(0) : (node >> exposure);
    node = fs["saturation"];
    node.isNone() ? void(0) : (node >> saturation);
    node = fs["gain"];
    node.isNone() ? void(0) : (node >> gain);
    node = fs["b_gain"];
    if (!node.isNone())
    {
        int tmp{};
        node >> tmp;
        b_gain = static_cast<uint32_t>(tmp);
    }
    node = fs["g_gain"];
    if (!node.isNone())
    {
        int tmp{};
        node >> tmp;
        g_gain = static_cast<uint32_t>(tmp);
    }
    node = fs["r_gain"];
    if (!node.isNone())
    {
        int tmp{};
        node >> tmp;
        r_gain = static_cast<uint32_t>(tmp);
    }
    node = fs["auto_exposure"];
    node.isNone() ? void(0) : (node >> auto_exposure);
    node = fs["auto_wb"];
    node.isNone() ? void(0) : (node >> auto_wb);
    node = fs["grab_mode"];
    node.isNone() ? void(0) : (node >> grab_mode);
    node = fs["retrieve_mode"];
    node.isNone() ? void(0) : (node >> retrieve_mode);
    node = fs["serial_number"];
    node.isNone() ? void(0) : (node >> serial_number);

    return true;
}

} // rm::para
